    uis_rvc2 g 0x562 (mword_of_int 0x8082 : mword 16) udec_8082.
  Qed.

  (* ---------------- <close> @ 0x544 ---------------- *)

  (* 0x544  c.li  (RVC, 4-aligned) *)
  Lemma uis_grep_544 (g : gname) :
    grep_code g -∗
    uinstr_is g (mword_of_int 0x544) true
      (C_LI (mword_of_int 21 : mword 6, Regidx (mword_of_int 17))).
  Proof using .
    iIntros "#Ht".
    uis_rvc4 g 0x544 (mword_of_int 0x48d5 : mword 16) udec_48d5
      (mword_of_int 0x007348d5 : mword 32).
  Qed.

  (* 0x546  ecall  (base, 2 mod 4 -> split fetch) *)
  Lemma uis_grep_546 (g : gname) :
    grep_code g -∗
    uinstr_is g (mword_of_int 0x546) false
      (ECALL tt).
  Proof using .
    iIntros "#Ht".
    uis_base g 0x546 (mword_of_int 0x00000073 : mword 32) udec_00000073.
  Qed.

  (* 0x54a  c.jr  (RVC, 2 mod 4) *)
  Lemma uis_grep_54a (g : gname) :
    grep_code g -∗
    uinstr_is g (mword_of_int 0x54a) true
      (C_JR (Regidx (mword_of_int 1))).
  Proof using .
    iIntros "#Ht".
    uis_rvc2 g 0x54a (mword_of_int 0x8082 : mword 16) udec_8082.
  Qed.

  (* ---------------- <exit> @ 0x51c ---------------- *)

  (* 0x51c  c.li  (RVC, 4-aligned) *)
  Lemma uis_grep_51c (g : gname) :
    grep_code g -∗
    uinstr_is g (mword_of_int 0x51c) true
      (C_LI (mword_of_int 2 : mword 6, Regidx (mword_of_int 17))).
  Proof using .
    iIntros "#Ht".
    uis_rvc4 g 0x51c (mword_of_int 0x4889 : mword 16) udec_4889
      (mword_of_int 0x00734889 : mword 32).
  Qed.

  (* 0x51e  ecall  (base, 2 mod 4 -> split fetch) *)
  Lemma uis_grep_51e (g : gname) :
    grep_code g -∗
    uinstr_is g (mword_of_int 0x51e) false
      (ECALL tt).
  Proof using .
    iIntros "#Ht".
    uis_base g 0x51e (mword_of_int 0x00000073 : mword 32) udec_00000073.
  Qed.

  (* 0x522  c.jr  (RVC, 2 mod 4) *)
  Lemma uis_grep_522 (g : gname) :
    grep_code g -∗
    uinstr_is g (mword_of_int 0x522) true
      (C_JR (Regidx (mword_of_int 1))).
  Proof using .
    iIntros "#Ht".
    uis_rvc2 g 0x522 (mword_of_int 0x8082 : mword 16) udec_8082.
  Qed.

  (* =================================================================== *)
  (* §3 Where the catalog comes from.                                      *)
  (* =================================================================== *)

  (* [grep_code] is defined above, at the top of the section, because every
     per-pc lemma consumes it. This is its INTRODUCTION, and the ONE place in
     the whole development where the program's bytes meet the process image:
     the entry hands out [utext_all gt M pm] -- the text half of the heap,
     over the image the kernel actually loaded -- and the two section
     hypotheses say that image contains the dump ([grep_text_sub]) and that
     the executable segment is X-and-not-W ([Hx]), which is what puts those
     bytes in the TEXT half rather than the data one. Both are discharged
     HERE, once, instead of in each of the 601 per-pc lemmas. *)

  (* AND THE READ-ONLY IMAGE BESIDE IT. A program's string LITERALS are not
     in [GrepInstrs.grep_bytes] and they are not in the data half either:
     .rodata shares the EXECUTABLE segment's pages, so its bytes are
     X-and-not-W and the heap files them under [γt] exactly as it files the
     code. This program's literals land at 0xb16..0x10cc, inside the R-X
     segment, and a printf-family walk LOADS them one byte at a time. This is
     the part of [GrepData.grep_data] that lands there -- everything below
     the end of the executable segment -- and [UserHeap.utext_str_of_img]
     cuts a literal out of it at a concrete base and length. *)
  Definition grep_ro : gmap Z (bv 8) :=
    filter (fun kv => (kv.1 < 8192)%Z) GrepData.grep_data.

  Definition grep_rodata (g : gname) : iProp Σ := utext_img g grep_ro.

  Global Instance grep_rodata_persistent g : Persistent (grep_rodata g).
  Proof using . apply _. Qed.

  Global Typeclasses Opaque grep_rodata.

  Lemma grep_rodata_of_text : utext_all gt M pm -∗ grep_rodata gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               grep_ro !! a = Some b -> M !! a = Some b).
    { intros a b Hb. apply map_lookup_filter_Some in Hb as [Hb _].
      exact (Hsub2 a b Hb). }
    assert (Hp : forall a : Z, is_Some (grep_ro !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply map_lookup_filter_Some in Hb as [Hb Hlt].
      apply Hx.
      pose proof (grep_data_key_nonneg a b Hb) as Hge.
      simpl in Hlt. lia. }
    iIntros "#Ht". rewrite /grep_rodata.
    iApply (utext_img_of_all gt M pm grep_ro Hin Hp with "Ht").
  Qed.

  Lemma grep_code_of_text : utext_all gt M pm -∗ grep_code gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               GrepInstrs.grep_bytes !! a = Some b -> M !! a = Some b)
      by exact Hsub.
    assert (Hp : forall a : Z, is_Some (GrepInstrs.grep_bytes !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply Hx.
      pose proof (grep_bytes_key_lt a b Hb) as Hlt.
      pose proof (grep_bytes_key_nonneg a b Hb) as Hge. lia. }
    iIntros "#Ht". rewrite /grep_code.
    iApply (utext_img_of_all gt M pm GrepInstrs.grep_bytes Hin Hp with "Ht").
  Qed.

End UCodeGrep.
